const folderId = 'ВСТАВЬТЕ_FOLDER_ID';
if (folderId === 'ВСТАВЬТЕ_FOLDER_ID') throw new Error('Настройте Folder ID в узле «Параметры Wordstat».');
const { masks, niche, regions } = $input.first().json.body;
if (!Array.isArray(masks) || !masks.length || !Array.isArray(regions) || !String(niche).trim()) {
  throw new Error('Проверьте маски, тематику и коды регионов.');
}
return masks.map(mask => ({ json: { mask, niche, folderId, regions } }));

// Рекурсивный (BFS) сбор семантики: из каждой фразы берём results + associations,
// каждую новую фразу с частотностью >= 50 кладём в очередь на дальнейший разбор,
// фразы с частотностью < 50 сохраняем как лист (дальше не разворачиваем).
// ЗАЩИТА ОТ ЛИМИТА WORDSTAT (100 запросов/час) И ОТ ТАЙМ-АУТА НОДЫ (300 сек):
// обход останавливается мягко (без ошибки), как только сработает первое из двух ограничений —
// либо MAX_TOTAL_QUERIES запросов, либо MAX_RUNTIME_MS времени с начала выполнения.
// Ошибки Wordstat не глотаются молча — при сбое запроса нода упадёт с понятной ошибкой.

const apiKey = 'ВСТАВЬТЕ_КЛЮЧ_WORDSTAT';
if (apiKey === 'ВСТАВЬТЕ_КЛЮЧ_WORDSTAT') throw new Error('В настройках агента отсутствует ключ Wordstat.');

const helpers = this.helpers; // используем встроенный HTTP-клиент n8n вместо fetch (в Code-ноде fetch недоступен)

const ENDPOINT = 'https://searchapi.api.cloud.yandex.net/v2/wordstat/topRequests';
const FREQ_THRESHOLD = 50;
const REQUEST_DELAY_MS = 600;
const MAX_TOTAL_QUERIES = 80; // защитный лимит на весь прогон (у Wordstat лимит 100 запросов/час)
const MAX_RUNTIME_MS = 270000; // 4.5 минуты — с запасом под тайм-аут ноды в 300 сек
const startTime = Date.now();

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function queryWordstat(phrase, folderId, regions) {
  const body = { phrase, numPhrases: '300', folderId };
  if (regions && regions.length) body.regions = regions;
  try {
    const data = await helpers.httpRequest({
      method: 'POST',
      url: ENDPOINT,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Api-Key ${apiKey}`
      },
      body,
      json: true
    });
    return data;
  } catch (err) {
    throw new Error('Wordstat не вернул данные для фразы: ' + phrase);
  }
}

const finalOutput = [];
let totalQueryCount = 0;
let limitReached = false;
let limitReason = '';

for (const item of $input.all()) {
  if (limitReached) break;
  const { mask, niche, folderId, regions } = item.json;
  const visitedQueried = new Set();
  const collectedPhrases = new Set();
  const queue = [mask];

  while (queue.length > 0) {
    if (totalQueryCount >= MAX_TOTAL_QUERIES) {
      limitReached = true;
      limitReason = `лимит ${MAX_TOTAL_QUERIES} запросов`;
      break;
    }
    if (Date.now() - startTime > MAX_RUNTIME_MS) {
      limitReached = true;
      limitReason = `лимит времени ${Math.round(MAX_RUNTIME_MS / 1000)} сек`;
      break;
    }
    const phrase = queue.shift();
    const normKey = phrase.toLowerCase().trim();
    if (visitedQueried.has(normKey)) continue;
    visitedQueried.add(normKey);

    const data = await queryWordstat(phrase, folderId, regions);
    totalQueryCount++;
    await sleep(REQUEST_DELAY_MS);

    const candidates = [...(data.results || []), ...(data.associations || [])];
    for (const c of candidates) {
      const cPhrase = c.phrase;
      if (!cPhrase) continue;
      const cKey = cPhrase.toLowerCase().trim();
      const freq = Number(c.count || 0);

      if (!collectedPhrases.has(cKey)) {
        collectedPhrases.add(cKey);
        finalOutput.push({ json: { phrase: cPhrase, freq, niche } });
      }
      if (freq >= FREQ_THRESHOLD && !visitedQueried.has(cKey)) {
        queue.push(cPhrase);
      }
    }
  }
}

if (limitReached) {
  finalOutput.push({ json: {
    phrase: '__LIMIT_REACHED__',
    freq: 0,
    niche: `Достигнут защитный лимит (${limitReason}). Обход остановлен раньше, чем прошёл все ветки. Всего успешных запросов: ${totalQueryCount}.`
  } });
}

return finalOutput;

const rows = new Map();
for (const { json } of $input.all()) {
  const phrase = String(json.phrase ?? '').trim();
  if (!phrase || phrase === '__LIMIT_REACHED__') continue;
  const key = phrase.toLowerCase();
  const freq = Number(json.freq);
  if (!Number.isSafeInteger(freq) || freq < 0) continue;
  if (!rows.has(key) || rows.get(key).freq < freq) rows.set(key, { phrase, freq });
}
const filtered = [...rows.values()].filter(row => row.freq > 0);
const niche = $('Параметры Wordstat').first().json.niche;
const output = [];
for (let index = 0; index < filtered.length; index += 40) {
  output.push({ json: { hasPhrases: true, niche, rows: filtered.slice(index, index + 40) } });
}
return output.length ? output : [{ json: { hasPhrases: false } }];

const packs = $('Подготовка пакетов').all();
const results = $input.all();
if (packs.length !== results.length) throw new Error('Claude вернул неполный набор ответов.');
const classified = [];
for (let index = 0; index < packs.length; index++) {
  const rows = packs[index].json.rows;
  const raw = results[index].json.content?.find(block => block.type === 'text')?.text ?? '';
  let result;
  try { result = JSON.parse(raw.trim().replace(/^```(?:json)?\s*|\s*```$/gi, '')); }
  catch { throw new Error('Claude вернул некорректный JSON для пакета ' + (index + 1)); }
  if (!Array.isArray(result?.irrelevant) || result.irrelevant.some(n => !Number.isInteger(n) || n < 1 || n > rows.length)) {
    throw new Error('Claude вернул некорректные позиции фраз для пакета ' + (index + 1));
  }
  const rejected = new Set(result.irrelevant);
  rows.forEach((row, i) => classified.push({ ...row, relevant: !rejected.has(i + 1) }));
}
return [{ json: { classified } }];

const raw = $('Сбор Wordstat').all().map(item => item.json);
const warning = raw.find(row => row.phrase === '__LIMIT_REACHED__')?.niche ?? '';
const rawRows = raw.filter(row => row.phrase && row.phrase !== '__LIMIT_REACHED__');
const classified = $input.first().json.classified ?? [];
const csv = rows => 'phrase,freq\r\n' + rows.map(row =>
  '"' + String(row.phrase).replace(/"/g, '""') + '",' + Number(row.freq || 0)
).join('\r\n');
return [{ json: { warning, files: {
  '01_all_phrases.csv': csv(rawRows),
  '02_empty_phrases.csv': csv(rawRows.filter(row => row.freq <= 0)),
  '03_clean_no_empty.csv': csv(rawRows.filter(row => row.freq > 0)),
  '04_irrelevant.csv': csv(classified.filter(row => !row.relevant)),
  '05_final_clean.csv': csv(classified.filter(row => row.relevant))
} } }];
